import { readdir } from 'node:fs/promises';
import path from 'node:path';
import type { Page } from './types';

export async function collectMarkdownFiles(dir: string): Promise<string[]> {
  const files: string[] = [];
  const entries = await readdir(dir, { withFileTypes: true });
  for (const entry of entries) {
    const full = path.join(dir, entry.name);
    if (entry.isDirectory()) {
      files.push(...(await collectMarkdownFiles(full)));
    } else if (/\.(md|markdown)$/i.test(entry.name)) {
      files.push(full);
    }
  }
  return files;
}

export function toSlug(relativePath: string): string {
  return relativePath
    .replace(/\.(md|markdown)$/i, '')
    .split(/[\\/]/)
    .map((part) => part.replace(/[^a-zA-Z0-9]+/g, '-').replace(/^-+|-+$/g, ''))
    .filter(Boolean)
    .join('/');
}

export function normalizeTags(tags: string | string[] | undefined): string[] {
  if (Array.isArray(tags)) return tags.map(String);
  if (typeof tags === 'string') {
    return tags
      .split(',')
      .map((tag) => tag.trim())
      .filter(Boolean);
  }
  return [];
}

export function pageTitle(relativePath: string): string {
  const parsed = path.parse(relativePath);
  return parsed.name
    .split(/[-_\s]+/)
    .filter(Boolean)
    .map((word) => word.charAt(0).toUpperCase() + word.slice(1))
    .join(' ');
}

export function comparePages(a: Page, b: Page): number {
  if (a.date !== b.date) {
    return a.date < b.date ? 1 : -1;
  }
  return a.slug.localeCompare(b.slug);
}

function escapeHtml(value: string): string {
  return value
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;');
}

export function renderPage(page: Page): string {
  const tags = page.tags.map((tag) => `<a class="tag" href="#/tags/${escapeHtml(tag)}">${escapeHtml(tag)}</a>`).join(' ');
  const date = page.date ? `<time datetime="${escapeHtml(page.date)}">${escapeHtml(page.date)}</time>` : '';

  return `<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>${escapeHtml(page.title)}</title>
</head>
<body>
  <header>
    <a class="back" href="index.html">&larr; Home</a>
    <h1>${escapeHtml(page.title)}</h1>
    ${date ? `<p class="meta">${date}</p>` : ''}
    ${tags ? `<p class="tags">${tags}</p>` : ''}
  </header>
  <main>
${page.html}
  </main>
</body>
</html>
`;
}

export function renderIndex(pages: Page[]): string {
  const items = pages
    .map(
      (page) => `    <li><a href="${escapeHtml(page.slug)}.html">${escapeHtml(page.title)}</a>${page.date ? ` <time datetime="${escapeHtml(page.date)}">${escapeHtml(page.date)}</time>` : ''}</li>`,
    )
    .join('\n');

  return `<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>Index</title>
</head>
<body>
  <h1>Index</h1>
  <ul class="pages">
${items}
  </ul>
</body>
</html>
`;
}

import type { Page } from './types';

export type PluginHook = 'onStart' | 'beforeBuild' | 'afterBuild' | 'onFile' | 'onEnd';

export interface PluginFile extends Page {
  raw: string;
  contentDir: string;
}

export interface PluginContext {
  contentDir: string;
  outputDir: string;
  templatesDir: string;
  port: number;
  pages: Page[];
  files: string[];
  options: Record<string, unknown>;
  [key: string]: unknown;
}

export interface Plugin {
  name: string;
  onStart?(context: PluginContext): void | Promise<void>;
  beforeBuild?(context: PluginContext): void | Promise<void>;
  afterBuild?(context: PluginContext): void | Promise<void>;
  onFile?(page: PluginFile, context: PluginContext): void | PluginFile | Promise<void | PluginFile>;
  onEnd?(context: PluginContext): void | Promise<void>;
}

export class PluginManager {
  private readonly plugins: Plugin[] = [];

  constructor(plugins: Plugin[] = []) {
    for (const plugin of plugins) {
      this.register(plugin);
    }
  }

  register(plugin: Plugin): void {
    this.plugins.push(plugin);
  }

  getPlugins(): Plugin[] {
    return [...this.plugins];
  }

  async runHook(hook: 'onStart' | 'beforeBuild' | 'afterBuild' | 'onEnd', context: PluginContext): Promise<void> {
    for (const plugin of this.plugins) {
      const fn = plugin[hook];
      if (fn) {
        await fn(context);
      }
    }
  }

  async runOnFile(page: PluginFile, context: PluginContext): Promise<PluginFile> {
    let current = page;
    for (const plugin of this.plugins) {
      const fn = plugin.onFile;
      if (fn) {
        const result = await fn(current, context);
        if (result) {
          current = result;
        }
      }
    }
    return current;
  }
}

import { existsSync, readFileSync } from 'node:fs';
import path from 'node:path';
import * as ts from 'typescript';
import type { Plugin } from './plugin';

export interface SSGConfig {
  plugins?: Plugin[];
  contentDir?: string;
  outputDir?: string;
  templatesDir?: string;
  port?: number;
  [key: string]: unknown;
}

export function loadConfig(configPath = 'ssg.config.ts'): SSGConfig | undefined {
  const resolved = path.resolve(configPath);
  if (!existsSync(resolved)) {
    return undefined;
  }
  const loaded = loadTsModule(resolved);
  const candidate = loaded as { default?: SSGConfig };
  return (candidate?.default ?? loaded) as SSGConfig;
}

function loadTsModule(filename: string, seen: Set<string> = new Set()): unknown {
  const resolved = path.resolve(filename);
  if (seen.has(resolved)) {
    return {};
  }
  seen.add(resolved);

  const source = readFileSync(resolved, 'utf8');
  const js = ts.transpileModule(source, {
    compilerOptions: {
      module: ts.ModuleKind.CommonJS,
      target: ts.ScriptTarget.ES2020,
      esModuleInterop: true,
    },
    reportDiagnostics: false,
  }).outputText;

  const moduleObject = { exports: {} };
  const baseDir = path.dirname(resolved);
  const localRequire = (id: string): unknown => {
    if (id.startsWith('.') || path.isAbsolute(id)) {
      return resolveTsOrJs(path.join(baseDir, id), localRequire, seen);
    }
    return require(id);
  };

  const fn = new Function('module', 'exports', 'require', '__dirname', '__filename', js);
  fn(moduleObject, moduleObject.exports, localRequire, baseDir, resolved);
  return moduleObject.exports;
}

function resolveTsOrJs(base: string, localRequire: (id: string) => unknown, seen: Set<string>): unknown {
  const candidates = [
    base,
    `${base}.ts`,
    `${base}.tsx`,
    `${base}.js`,
    `${base}.jsx`,
    path.join(base, 'index.ts'),
    path.join(base, 'index.js'),
  ];
  for (const candidate of candidates) {
    if (existsSync(candidate)) {
      if (/\.tsx?$/.test(candidate)) {
        return loadTsModule(candidate, seen);
      }
      return require(candidate);
    }
  }
  throw new Error(`Cannot resolve module: ${base}`);
}

import { parseMarkdown, renderMarkdown } from '../markdown';
import { normalizeTags, pageTitle } from '../render';
import type { Plugin, PluginContext, PluginFile } from '../plugin';

export class MarkdownPlugin implements Plugin {
  readonly name = 'markdown';

  async onFile(page: PluginFile, context: PluginContext): Promise<void> {
    const { data, body } = parseMarkdown(page.raw);
    page.title = (data.title && data.title.trim()) || pageTitle(page.source);
    page.date = (data.date && data.date.trim()) || '';
    page.tags = normalizeTags(data.tags);
    page.html = renderMarkdown(body);
    page.template = typeof data.template === 'string' && data.template.trim() ? data.template.trim() : undefined;
    page.layout = typeof data.layout === 'string' && data.layout.trim() ? data.layout.trim() : undefined;
    page.data = { ...(data as Record<string, unknown>) };
  }
}

import { DEFAULT_TEMPLATE_DIR, TemplateEngine } from '../templates';
import { renderPage } from '../render';
import type { Plugin, PluginContext, PluginFile } from '../plugin';

export class TemplatePlugin implements Plugin {
  readonly name = 'templates';

  private readonly engine: TemplateEngine;

  constructor(templatesDir: string = DEFAULT_TEMPLATE_DIR) {
    this.engine = new TemplateEngine(templatesDir);
  }

  async onStart(context: PluginContext): Promise<void> {
    await this.engine.load();
  }

  async onFile(page: PluginFile, context: PluginContext): Promise<void> {
    page.html = this.engine.hasTemplates() ? this.engine.renderPage(page, page.html) : renderPage(page);
  }
}

import { createServer, type Server } from 'node:http';
import { readFile, stat } from 'node:fs/promises';
import path from 'node:path';
import { WebSocket, WebSocketServer } from 'ws';
import chokidar, { type FSWatcher } from 'chokidar';
import { buildSite } from '../generator';
import type { Plugin, PluginContext } from '../plugin';

export const DEFAULT_PORT = 3000;
export const WS_PATH = '/__ssg_reload__';
export const RELOAD_MESSAGE = 'reload';

export interface ServeOptions {
  contentDir: string;
  outputDir: string;
  templatesDir: string;
  port: number;
  plugins?: Plugin[];
  configPath?: string;
}

export interface ServeHandle {
  server: Server;
  wss: WebSocketServer;
  watcher: FSWatcher;
  stop: () => Promise<void>;
}

const MIME_TYPES: Record<string, string> = {
  '.html': 'text/html; charset=utf-8',
  '.htm': 'text/html; charset=utf-8',
  '.css': 'text/css; charset=utf-8',
  '.js': 'text/javascript; charset=utf-8',
  '.mjs': 'text/javascript; charset=utf-8',
  '.json': 'application/json; charset=utf-8',
  '.map': 'application/json; charset=utf-8',
  '.txt': 'text/plain; charset=utf-8',
  '.xml': 'application/xml; charset=utf-8',
  '.png': 'image/png',
  '.jpg': 'image/jpeg',
  '.jpeg': 'image/jpeg',
  '.gif': 'image/gif',
  '.svg': 'image/svg+xml',
  '.webp': 'image/webp',
  '.ico': 'image/x-icon',
  '.woff': 'font/woff',
  '.woff2': 'font/woff2',
  '.ttf': 'font/ttf',
  '.mp4': 'video/mp4',
  '.webm': 'video/webm',
  '.pdf': 'application/pdf',
};

export function contentType(filePath: string): string {
  return MIME_TYPES[path.extname(filePath).toLowerCase()] ?? 'application/octet-stream';
}

export function liveReloadScript(port: number): string {
  return `<script data-ssg-live-reload>
(function () {
  var protocol = window.location.protocol === 'https:' ? 'wss://' : 'ws://';
  var socket = new WebSocket(protocol + window.location.host + '${WS_PATH}');
  socket.onmessage = function (event) {
    if (event.data === '${RELOAD_MESSAGE}') {
      window.location.reload();
    }
  };
})();
</script>`;
}

export function injectLiveReloadScript(html: string, port: number): string {
  const script = liveReloadScript(port);
  if (html.includes('</body>')) {
    return html.replace('</body>', `${script}\n</body>`);
  }
  if (html.includes('</head>')) {
    return html.replace('</head>', `${script}\n</head>`);
  }
  return `${html}\n${script}`;
}

export async function resolveFile(outputDir: string, pathname: string): Promise<string | null> {
  const root = path.resolve(outputDir);
  const candidates: string[] = [];
  const normalized = path.posix.normalize(pathname).replace(/^\/+/, '');

  if (normalized === '' || normalized === '.') {
    candidates.push('index.html');
  } else {
    candidates.push(normalized);
    if (!path.posix.extname(normalized)) {
      candidates.push(`${normalized}.html`);
      candidates.push(path.posix.join(normalized, 'index.html'));
    }
  }

  for (const candidate of candidates) {
    const full = path.resolve(root, candidate);
    if (full !== root && !full.startsWith(root + path.sep)) {
      continue;
    }
    try {
      const st = await stat(full);
      if (st.isFile()) {
        return full;
      }
    } catch {
      // continue looking
    }
  }

  return null;
}

async function startDevServer(options: ServeOptions): Promise<ServeHandle> {
  const { contentDir, outputDir, templatesDir, port, plugins, configPath } = options;

  await buildSite(contentDir, outputDir, { templatesDir, plugins, configPath });

  const wss = new WebSocketServer({ noServer: true });
  const server = createServer(async (req, res) => {
    if (req.method !== 'GET' && req.method !== 'HEAD') {
      res.writeHead(405, { 'Content-Type': 'text/plain; charset=utf-8' });
      res.end('Method Not Allowed');
      return;
    }

    let pathname: string;
    try {
      pathname = decodeURIComponent(new URL(req.url ?? '/', 'http://localhost').pathname);
    } catch {
      res.writeHead(400, { 'Content-Type': 'text/plain; charset=utf-8' });
      res.end('Bad Request');
      return;
    }

    const file = await resolveFile(outputDir, pathname);
    if (file === null) {
      res.writeHead(404, { 'Content-Type': 'text/plain; charset=utf-8' });
      res.end('Not Found');
      return;
    }

    let body = await readFile(file);
    const isHtml = path.extname(file).toLowerCase() === '.html';
    if (isHtml) {
      body = Buffer.from(injectLiveReloadScript(body.toString('utf8'), port), 'utf8');
    }

    res.writeHead(200, {
      'Content-Type': contentType(file),
      'Cache-Control': 'no-cache',
    });
    if (req.method === 'HEAD') {
      res.end();
    } else {
      res.end(body);
    }
  });

  server.on('upgrade', (req, socket, head) => {
    let url: URL;
    try {
      url = new URL(req.url ?? '/', 'http://localhost');
    } catch {
      socket.destroy();
      return;
    }
    if (url.pathname !== WS_PATH) {
      socket.destroy();
      return;
    }
    wss.handleUpgrade(req, socket, head, (ws) => {
      wss.emit('connection', ws, req);
    });
  });

  function broadcastReload(): void {
    for (const client of wss.clients) {
      if (client.readyState === WebSocket.OPEN) {
        client.send(RELOAD_MESSAGE);
      }
    }
  }

  const watcher = chokidar.watch([contentDir, templatesDir], { ignoreInitial: true });

  await new Promise<void>((resolve) => {
    watcher.once('ready', () => resolve());
  });
  await new Promise<void>((resolve) => setTimeout(resolve, 100));

  let timer: NodeJS.Timeout | undefined;
  const scheduleRebuild = (): void => {
    if (timer) {
      clearTimeout(timer);
    }
    timer = setTimeout(async () => {
      try {
        await buildSite(contentDir, outputDir, { templatesDir, plugins, configPath });
        console.log('Rebuilt site');
        broadcastReload();
      } catch (err) {
        console.error(`Build failed: ${err instanceof Error ? err.message : String(err)}`);
      }
    }, 80);
  };
  watcher.on('all', scheduleRebuild);

  await new Promise<void>((resolve, reject) => {
    const onError = (err: Error): void => {
      server.off('listening', onListening);
      reject(err);
    };
    const onListening = (): void => {
      server.off('error', onError);
      resolve();
    };
    server.once('error', onError);
    server.once('listening', onListening);
    server.listen(port);
  });

  let stopped = false;
  async function stop(): Promise<void> {
    if (stopped) return;
    stopped = true;
    if (timer) {
      clearTimeout(timer);
      timer = undefined;
    }
    await watcher.close();
    for (const client of wss.clients) {
      client.terminate();
    }
    wss.close();
    await new Promise<void>((resolve) => server.close(() => resolve()));
  }

  return { server, wss, watcher, stop };
}

export class DevServerPlugin implements Plugin {
  readonly name = 'dev-server';

  private readonly options: ServeOptions;
  private handle: ServeHandle | undefined;

  constructor(options: ServeOptions) {
    this.options = options;
  }

  async onStart(context: PluginContext): Promise<void> {
    await this.start();
  }

  async onEnd(context: PluginContext): Promise<void> {
    await this.stop();
  }

  async start(): Promise<void> {
    if (this.handle) {
      return;
    }
    this.handle = await startDevServer(this.options);
  }

  async stop(): Promise<void> {
    if (this.handle) {
      const handle = this.handle;
      this.handle = undefined;
      await handle.stop();
    }
  }

  getServer(): Server | null {
    return this.handle?.server ?? null;
  }

  getWss(): WebSocketServer | null {
    return this.handle?.wss ?? null;
  }

  getWatcher(): FSWatcher | null {
    return this.handle?.watcher ?? null;
  }

  toHandle(): ServeHandle {
    if (!this.handle) {
      throw new Error('Dev server has not been started');
    }
    return this.handle;
  }
}

import { mkdir, readFile, writeFile } from 'node:fs/promises';
import path from 'node:path';
import { DEFAULT_TEMPLATE_DIR } from './templates';
import { collectMarkdownFiles, comparePages, renderIndex, toSlug } from './render';
import { PluginManager, type Plugin, type PluginContext, type PluginFile } from './plugin';
import { MarkdownPlugin } from './plugins/markdown';
import { TemplatePlugin } from './plugins/templates';
import { loadConfig } from './config';
import type { BuildResult, Page } from './types';

export interface SSGEngineOptions {
  plugins?: Plugin[];
  templatesDir?: string;
  port?: number;
  configPath?: string;
}

export class SSGEngine {
  private readonly manager: PluginManager;
  private readonly options: SSGEngineOptions;

  constructor(options: SSGEngineOptions = {}) {
    this.options = options;
    const config = loadConfig(options.configPath ?? 'ssg.config.ts');
    const configured = [...(config?.plugins ?? []), ...(options.plugins ?? [])];

    const plugins: Plugin[] = [];
    if (!configured.some((plugin) => plugin.name === 'markdown')) {
      plugins.push(new MarkdownPlugin());
    }
    if (!configured.some((plugin) => plugin.name === 'templates')) {
      plugins.push(new TemplatePlugin(options.templatesDir));
    }
    plugins.push(...configured);

    this.manager = new PluginManager(plugins);
  }

  getPlugins(): Plugin[] {
    return this.manager.getPlugins();
  }

  addPlugin(plugin: Plugin): void {
    this.manager.register(plugin);
  }

  async build(contentDir: string, outputDir: string): Promise<BuildResult> {
    const templatesDir = this.options.templatesDir ?? DEFAULT_TEMPLATE_DIR;
    const context: PluginContext = {
      contentDir,
      outputDir,
      templatesDir,
      port: this.options.port ?? 3000,
      pages: [],
      files: [],
      options: { ...this.options },
    };

    await this.manager.runHook('onStart', context);
    await this.manager.runHook('beforeBuild', context);

    const works = await this.collectPages(contentDir);
    const pages: PluginFile[] = [];
    for (const work of works) {
      pages.push(await this.manager.runOnFile(work, context));
    }
    pages.sort(comparePages);
    context.pages = pages;

    await mkdir(outputDir, { recursive: true });
    const files: string[] = [];
    for (const page of pages) {
      const outPath = path.join(outputDir, `${page.slug}.html`);
      await mkdir(path.dirname(outPath), { recursive: true });
      await writeFile(outPath, page.html, 'utf8');
      files.push(outPath);
    }
    const indexPath = path.join(outputDir, 'index.html');
    await writeFile(indexPath, renderIndex(pages), 'utf8');
    files.push(indexPath);
    context.files = files;

    await this.manager.runHook('afterBuild', context);
    await this.manager.runHook('onEnd', context);

    return { pages, files };
  }

  private async collectPages(contentDir: string): Promise<PluginFile[]> {
    const files = await collectMarkdownFiles(contentDir);
    const works: PluginFile[] = [];
    for (const file of files) {
      const raw = await readFile(file, 'utf8');
      const relative = path.relative(contentDir, file);
      works.push({
        title: '',
        date: '',
        tags: [],
        slug: toSlug(relative),
        source: relative,
        html: '',
        raw,
        contentDir,
      });
    }
    return works;
  }
}

export type { Page };

import { readFile } from 'node:fs/promises';
import path from 'node:path';
import { parseMarkdown, renderMarkdown } from './markdown';
import { SSGEngine } from './engine';
import { collectMarkdownFiles, comparePages, normalizeTags, pageTitle, toSlug } from './render';
import type { Plugin } from './plugin';
import type { BuildResult, Page } from './types';

export const DEFAULT_CONTENT_DIR = 'content';
export const DEFAULT_OUTPUT_DIR = 'dist';

export interface BuildOptions {
  templatesDir?: string;
  plugins?: Plugin[];
  configPath?: string;
  port?: number;
}

export { collectMarkdownFiles, renderPage, renderIndex, toSlug } from './render';

export async function loadPages(contentDir: string): Promise<Page[]> {
  const files = await collectMarkdownFiles(contentDir);
  const pages: Page[] = [];

  for (const file of files) {
    const raw = await readFile(file, 'utf8');
    const { data, body } = parseMarkdown(raw);
    const relative = path.relative(contentDir, file);
    const slug = toSlug(relative);

    pages.push({
      title: (data.title && data.title.trim()) || pageTitle(relative),
      date: (data.date && data.date.trim()) || '',
      tags: normalizeTags(data.tags),
      slug,
      source: relative,
      html: renderMarkdown(body),
      template: typeof data.template === 'string' && data.template.trim() ? data.template.trim() : undefined,
      layout: typeof data.layout === 'string' && data.layout.trim() ? data.layout.trim() : undefined,
      data: { ...(data as Record<string, unknown>) },
    });
  }

  pages.sort(comparePages);
  return pages;
}

export async function buildSite(contentDir: string, outputDir: string, options: BuildOptions = {}): Promise<BuildResult> {
  const engine = new SSGEngine(options);
  return engine.build(contentDir, outputDir);
}

import { DevServerPlugin } from './plugins/dev-server';
import type { ServeHandle, ServeOptions } from './plugins/dev-server';

export {
  DEFAULT_PORT,
  WS_PATH,
  RELOAD_MESSAGE,
  ServeOptions,
  ServeHandle,
  contentType,
  liveReloadScript,
  injectLiveReloadScript,
  resolveFile,
} from './plugins/dev-server';

export async function startServe(options: ServeOptions): Promise<ServeHandle> {
  const plugin = new DevServerPlugin(options);
  await plugin.start();
  return plugin.toHandle();
}

export async function serve(options: ServeOptions): Promise<void> {
  const handle = await startServe(options);
  const { port, outputDir } = options;

  console.log(`Serving ${outputDir} at http://localhost:${port}`);
  console.log(`Watching for changes...`);

  const shutdown = (): void => {
    handle.stop().then(() => process.exit(0));
  };
  process.once('SIGINT', shutdown);
  process.once('SIGTERM', shutdown);
}

